"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}
PARAMETRIZED = {"truncate": Truncate}


def lookup(name: str):
    """Look up a step by its full name (may include ':arg')."""
    # Split on first colon to separate base name from argument
    if ":" in name:
        base_name, arg_str = name.split(":", 1)
    else:
        base_name = name
        arg_str = None

    if base_name in PARAMETRIZED:
        cls = PARAMETRIZED[base_name]
        if arg_str is None:
            raise ValueError(f"step {base_name!r} requires an argument, got {name!r}")
        try:
            length = int(arg_str)
        except ValueError:
            raise ValueError(f"step {base_name!r} expects a number, got {arg_str!r}")
        return cls(length)
    elif base_name in STEPS:
        return STEPS[base_name]
    else:
        all_names = sorted(set(list(STEPS.keys()) + list(PARAMETRIZED.keys())))
        raise KeyError(f"no step named {base_name!r}. Known: {', '.join(all_names)}")

